<!DOCTYPE html>
<html lang="en">
<head>
    <link rel=" canonical href=https://sazzad.wedevspro.com/case-study/madina-case-study/>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>Madina Clothing — WordPress E-commerce Case Study · Sazzad Hossain</title>
<meta name="description" content="Case study: Madina Clothing, an Islamic lifestyle WooCommerce store with a custom-built Shoppable Reel plugin, designed and developed by Sazzad Hossain (@developersazzad).">
<meta name="theme-color" content="#14281d">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,500;9..144,700&family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap" rel="stylesheet">
<style>
/* =========================================================
   MADINA CLOTHING — CASE STUDY
   Mobile-first · breakpoints: 420 / 580 / 768 / 990 / 1280
   ========================================================= */
:root{
  --ink:#122019; --ink-2:#3c4a42; --muted:#6c7a71;
  --green-900:#0f2219; --green-800:#14281d; --green-700:#1f3a2c; --green-500:#3d6b4a; --green-300:#8fb69a;
  --mint:#e7efe9; --cream:#f7f4ee; --paper:#fffdf9;
  --gold:#c9a45c; --gold-2:#e9d3a1;
  --r-lg:28px; --r-md:20px; --r-sm:14px;
  --shadow-3d: 0 1px 0 rgba(255,255,255,.6) inset, 0 -2px 0 rgba(0,0,0,.04) inset, 0 30px 60px -25px rgba(15,34,25,.35), 0 12px 24px -12px rgba(15,34,25,.25);
  --font-d:"Fraunces", Georgia, "Times New Roman", serif;
  --font-b:"Plus Jakarta Sans", system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
  --pad: 18px;
}
*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
body{font-family:var(--font-b);color:var(--ink);background:var(--cream);line-height:1.6;font-size:15px;overflow-x:hidden;-webkit-font-smoothing:antialiased}
img{max-width:100%;display:block}
a{color:inherit}
.wrap{width:100%;max-width:1200px;margin:0 auto;padding:0 var(--pad)}
.eyebrow{display:inline-flex;align-items:center;gap:8px;font-size:11px;font-weight:700;letter-spacing:.16em;text-transform:uppercase;color:var(--green-500)}
.eyebrow::before{content:"";width:22px;height:2px;border-radius:2px;background:currentColor}
h1,h2,h3{font-family:var(--font-d);font-weight:700;line-height:1.08;letter-spacing:-.01em}
.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}

/* ---------- Top bar ---------- */
.topbar{position:sticky;top:0;z-index:50;backdrop-filter:saturate(1.4) blur(14px);-webkit-backdrop-filter:saturate(1.4) blur(14px);background:rgba(247,244,238,.78);border-bottom:1px solid rgba(18,32,25,.06)}
.topbar .wrap{display:flex;align-items:center;justify-content:space-between;height:58px}
.brand{display:flex;align-items:center;gap:10px;text-decoration:none;font-weight:800;font-size:14px}
.brand-mark{width:34px;height:34px;border-radius:11px;display:grid;place-items:center;color:#fff;font-size:13px;background:linear-gradient(145deg,var(--green-500),var(--green-800));box-shadow:0 8px 16px -6px rgba(20,40,29,.6), inset 0 1px 0 rgba(255,255,255,.25)}
.brand small{display:none;font-weight:500;color:var(--muted)}
.pill-link{font-size:12px;font-weight:700;text-decoration:none;padding:9px 14px;border-radius:999px;background:var(--green-800);color:#fff;box-shadow:0 8px 18px -8px rgba(20,40,29,.7)}

/* ---------- HERO ---------- */
.hero{position:relative;padding:34px 0 40px;overflow:hidden}
.hero::before{content:"";position:absolute;right:-220px;top:-200px;width:620px;height:620px;border-radius:50%;background:radial-gradient(circle at 35% 35%,rgba(143,182,154,.55),rgba(143,182,154,0) 65%);pointer-events:none}
.hero-grid{display:grid;gap:34px;position:relative}
.hero h1{font-size:clamp(38px,11vw,84px);margin:14px 0 14px}
.hero h1 em{font-style:italic;color:var(--green-500);font-weight:500}
.lead{font-size:16px;color:var(--ink-2);max-width:560px}
.meta{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:22px}
.meta div{background:var(--paper);border-radius:var(--r-sm);padding:12px 14px;box-shadow:var(--shadow-3d)}
.meta dt{font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted);font-weight:700}
.meta dd{font-weight:700;font-size:13.5px;margin-top:2px}
.cta-row{display:flex;flex-wrap:wrap;gap:10px;margin-top:22px}
.btn{display:inline-flex;align-items:center;gap:8px;padding:13px 20px;border-radius:999px;text-decoration:none;font-weight:700;font-size:14px;transition:transform .25s ease, box-shadow .25s ease}
.btn-primary{color:#fff;background:linear-gradient(145deg,#4a7f58,var(--green-800));box-shadow:0 14px 28px -12px rgba(20,40,29,.75), inset 0 1px 0 rgba(255,255,255,.2)}
.btn-ghost{background:var(--paper);box-shadow:var(--shadow-3d)}
.btn:hover{transform:translateY(-2px)}
.btn svg{width:16px;height:16px}

/* 3D stage */
.stage{position:relative;height:420px;perspective:1400px;perspective-origin:50% 40%}
.stage-inner{position:absolute;inset:0;transform-style:flat;transition:transform .4s cubic-bezier(.2,.7,.2,1)}
.laptop{position:absolute;left:0;top:30px;width:92%;transform:perspective(1400px) rotateX(14deg) rotateY(-18deg) rotateZ(2deg);transform-style:preserve-3d;z-index:1}
.laptop-screen{background:#0d1712;border-radius:14px 14px 4px 4px;padding:8px;box-shadow:0 40px 70px -30px rgba(15,34,25,.6)}
.laptop-screen img{border-radius:6px;aspect-ratio:16/10;object-fit:cover;object-position:top;width:100%}
.laptop-base{height:12px;margin:0 -6%;background:linear-gradient(#d8dcd9,#a9b0ab);border-radius:0 0 16px 16px;box-shadow:0 20px 30px -12px rgba(15,34,25,.5)}
.phone{position:absolute;right:2%;bottom:6px;width:150px;aspect-ratio:9/19.3;border-radius:28px;background:#0d1712;padding:7px;z-index:4;transform:perspective(1000px) rotateX(8deg) rotateY(-24deg) rotateZ(-3deg);box-shadow:-30px 40px 60px -25px rgba(15,34,25,.65), inset 0 0 0 1.5px #2b3a32}
.phone::before{content:"";position:absolute;top:12px;left:50%;width:34%;height:14px;transform:translateX(-50%);background:#0d1712;border-radius:10px;z-index:3}
.phone-screen{width:100%;height:100%;border-radius:22px;overflow:hidden;background-color:#fff;background-image:url("data:image/jpeg;base64,");background-size:100% auto;background-repeat:no-repeat;animation:phoneScroll 26s ease-in-out infinite alternate}
@keyframes phoneScroll{0%,6%{background-position:50% 0%}94%,100%{background-position:50% 100%}}
.chip{position:absolute;z-index:6;display:flex;align-items:center;gap:8px;padding:9px 12px;border-radius:14px;background:rgba(255,253,249,.9);backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);font-size:12px;font-weight:700;box-shadow:var(--shadow-3d);white-space:nowrap;animation:float 6s ease-in-out infinite}
.chip b{font-family:var(--font-d);font-size:18px;color:var(--green-700)}
.chip i{width:26px;height:26px;border-radius:9px;display:grid;place-items:center;font-style:normal;color:#fff;background:linear-gradient(145deg,var(--gold),#a7833f);font-size:13px}
.chip-1{left:-2px;top:0}
.chip-2{right:0;top:8px;animation-delay:-2s}
.chip-3{left:6%;bottom:22px;animation-delay:-4s}
@keyframes float{0%,100%{translate:0 0}50%{translate:0 -10px}}
/* minimal 3d shapes */
.orb{position:absolute;border-radius:50%;background:radial-gradient(circle at 32% 28%,#fff 0,#e7efe9 18%,var(--green-300) 55%,var(--green-700) 100%);box-shadow:0 24px 40px -18px rgba(15,34,25,.6);animation:float 8s ease-in-out infinite}
.orb.gold{background:radial-gradient(circle at 32% 28%,#fff 0,var(--gold-2) 22%,var(--gold) 60%,#8a6a2c 100%)}
.ring{position:absolute;border-radius:50%;border:10px solid transparent;background:linear-gradient(var(--cream),var(--cream)) padding-box, linear-gradient(145deg,var(--gold-2),var(--gold) 50%,#8a6a2c) border-box;box-shadow:0 18px 30px -16px rgba(15,34,25,.5);animation:float 9s ease-in-out infinite}
.arch{position:absolute;width:70px;height:96px;border-radius:40px 40px 10px 10px;background:linear-gradient(160deg,#5a8d67,var(--green-800));box-shadow:inset 6px 6px 14px rgba(255,255,255,.18), inset -8px -10px 18px rgba(0,0,0,.25), 0 26px 40px -18px rgba(15,34,25,.6)}
.arch::after{content:"";position:absolute;inset:16px 16px 0;border-radius:30px 30px 0 0;background:linear-gradient(180deg,rgba(233,211,161,.9),rgba(201,164,92,.75));box-shadow:inset 0 6px 12px rgba(0,0,0,.18)}

/* ---------- Sections ---------- */
section.block{padding:56px 0;position:relative}
.sec-head{display:grid;gap:12px;margin-bottom:28px}
.sec-num{font-family:var(--font-d);font-size:64px;line-height:.8;color:transparent;-webkit-text-stroke:1.5px var(--green-300)}
.sec-head h2{font-size:clamp(30px,8vw,54px)}
.sec-head p{color:var(--ink-2);max-width:640px}

/* Challenge */
.challenge{background:var(--paper);border-radius:36px 36px 0 0;box-shadow:0 -20px 40px -30px rgba(15,34,25,.25)}
.problems{display:grid;gap:14px;counter-reset:p}
.problem{position:relative;padding:20px 18px 20px 18px;border-radius:var(--r-md);background:linear-gradient(180deg,#fff,var(--cream));box-shadow:var(--shadow-3d);transform-style:preserve-3d;transition:transform .35s cubic-bezier(.2,.7,.2,1)}
.problem .tag{display:inline-block;font-size:10px;font-weight:800;letter-spacing:.14em;text-transform:uppercase;color:#a7833f;background:#f6ecd7;padding:4px 9px;border-radius:999px}
.problem h3{font-size:20px;margin:10px 0 6px}
.problem p{font-size:14px;color:var(--ink-2)}
.problem .fix{margin-top:12px;padding-top:12px;border-top:1px dashed rgba(18,32,25,.15);font-size:13px;font-weight:600;color:var(--green-700);display:flex;gap:8px}
.problem .fix::before{content:"→";color:var(--gold)}
.reqs{margin-top:28px;padding:22px 18px;border-radius:var(--r-lg);background:var(--green-800);color:#e9f1eb;position:relative;overflow:hidden}
.reqs h3{font-size:22px;color:#fff;margin-bottom:12px}
.reqs ul{list-style:none;display:flex;flex-wrap:wrap;gap:8px}
.reqs li{font-size:12.5px;font-weight:600;padding:7px 12px;border-radius:999px;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.12)}
.reqs .orb{width:90px;height:90px;right:-24px;top:-24px;opacity:.9}

/* Solution */
.solution{background:linear-gradient(180deg,var(--paper) 0,var(--mint) 100%)}
.hero-feature{display:grid;gap:22px;padding:22px 18px;border-radius:32px;background:var(--green-900);color:#dfe9e2;position:relative;overflow:hidden;box-shadow:0 40px 70px -40px rgba(15,34,25,.9)}
.hero-feature::after{content:"";position:absolute;width:420px;height:420px;right:-160px;bottom:-200px;border-radius:50%;background:radial-gradient(circle,rgba(201,164,92,.35),transparent 65%)}
.badge-custom{display:inline-flex;gap:6px;align-items:center;font-size:11px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--green-900);background:linear-gradient(145deg,var(--gold-2),var(--gold));padding:6px 11px;border-radius:999px}
.hero-feature>*{min-width:0}
.hero-feature h3{color:#fff;font-size:clamp(26px,7vw,40px);margin:14px 0 10px}
.hero-feature p{font-size:14.5px;color:#b9c9be}
.ticks{list-style:none;display:grid;gap:9px;margin-top:16px;position:relative;z-index:1}
.ticks li{display:flex;gap:10px;font-size:13.5px;color:#dfe9e2}
.ticks li::before{content:"";flex:0 0 18px;height:18px;margin-top:2px;border-radius:6px;background:linear-gradient(145deg,#6aa37a,var(--green-500)) ;box-shadow:inset 0 1px 0 rgba(255,255,255,.3);-webkit-mask:none}
.ticks li span{display:block}
/* reel mock (3D) */
.reel-stage{position:relative;height:330px;perspective:1000px;z-index:1}
.reel{position:absolute;top:50%;left:50%;width:150px;aspect-ratio:9/16;border-radius:20px;overflow:hidden;background:#000 center top/cover no-repeat;box-shadow:0 30px 50px -20px rgba(0,0,0,.7);border:2px solid rgba(255,255,255,.08);transition:transform .5s cubic-bezier(.2,.7,.2,1)}
.reel.r1{background-image:url("data:image/jpeg;base64,");transform:translate(-50%,-50%) translateZ(60px);z-index:3}
.reel.r2{background-image:url("data:image/jpeg;base64,");transform:translate(-125%,-50%) rotateY(32deg) scale(.86);z-index:2;filter:brightness(.7)}
.reel.r3{background-image:url("data:image/jpeg;base64,");transform:translate(25%,-50%) rotateY(-32deg) scale(.86);z-index:2;filter:brightness(.7)}
.reel-ui{position:absolute;inset:auto 8px 8px 8px;padding:8px;border-radius:12px;background:rgba(255,255,255,.92);color:var(--ink);display:flex;align-items:center;gap:8px}
.reel-ui .t{flex:1;min-width:0;font-size:10px;font-weight:700;line-height:1.25}
.reel-ui .t small{display:block;color:var(--green-500);font-size:10px}
.reel-ui .go{font-size:9px;font-weight:800;background:var(--green-800);color:#fff;padding:5px 7px;border-radius:7px}
.reel .snd{position:absolute;top:8px;right:8px;width:24px;height:24px;border-radius:50%;background:rgba(0,0,0,.5);display:grid;place-items:center;color:#fff;font-size:11px}
.reel .play{position:absolute;top:40%;left:50%;transform:translate(-50%,-50%);width:42px;height:42px;border-radius:50%;background:rgba(255,255,255,.85);display:grid;place-items:center;box-shadow:0 8px 20px rgba(0,0,0,.35)}
.reel .play::after{content:"";border-left:13px solid var(--green-800);border-top:8px solid transparent;border-bottom:8px solid transparent;margin-left:4px}
.code{margin-top:16px;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:11.5px;line-height:1.7;background:rgba(0,0,0,.35);border:1px solid rgba(255,255,255,.08);border-radius:14px;padding:12px 14px;color:#cfe0d4;overflow-x:auto;position:relative;z-index:1;white-space:pre;max-width:100%}
.code .k{color:var(--gold-2)} .code .c{color:#7f978a}

.features{display:grid;gap:14px;margin-top:22px}
.feat{padding:20px 18px;border-radius:var(--r-md);background:var(--paper);box-shadow:var(--shadow-3d);transition:transform .35s cubic-bezier(.2,.7,.2,1);transform-style:preserve-3d}
.feat .ico{width:46px;height:46px;border-radius:15px;display:grid;place-items:center;background:linear-gradient(145deg,#f3f7f4,#d7e5db);box-shadow:inset 0 1px 0 #fff, 0 10px 18px -10px rgba(15,34,25,.5);margin-bottom:14px;transform:translateZ(30px)}
.feat .ico svg{width:22px;height:22px;stroke:var(--green-700);fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.feat h3{font-size:19px;margin-bottom:6px}
.feat p{font-size:13.5px;color:var(--ink-2)}

/* gallery */
.gallery{margin-top:34px;display:grid;gap:16px;perspective:1600px}
.shot{border-radius:18px;overflow:hidden;background:#fff;box-shadow:0 30px 60px -30px rgba(15,34,25,.55);border:6px solid #fff;transition:transform .5s cubic-bezier(.2,.7,.2,1)}
.shot img{width:100%;aspect-ratio:16/10;object-fit:cover;object-position:top}
.shot figcaption{font-size:12px;font-weight:700;padding:10px 6px 4px;color:var(--ink-2);display:flex;justify-content:space-between}
.shot figcaption span{color:var(--muted);font-weight:500}

/* impact */
.impact{margin-top:34px;display:grid;grid-template-columns:1fr 1fr;gap:12px}
.stat{padding:18px 14px;border-radius:var(--r-md);background:var(--paper);box-shadow:var(--shadow-3d);position:relative;overflow:hidden}
.stat b{display:block;font-family:var(--font-d);font-size:38px;line-height:1;color:var(--green-700)}
.stat span{font-size:12.5px;font-weight:600;color:var(--ink-2)}
.stat::after{content:"";position:absolute;right:-18px;top:-18px;width:60px;height:60px;border-radius:50%;background:radial-gradient(circle at 30% 30%,#fff,var(--mint) 40%,var(--green-300));opacity:.6}
.outcomes{margin-top:16px;display:grid;gap:12px}
.outcome{display:flex;gap:14px;align-items:flex-start;padding:16px;border-radius:var(--r-md);background:rgba(255,255,255,.6);border:1px solid rgba(18,32,25,.06)}
.outcome .n{flex:0 0 36px;width:36px;height:36px;border-radius:12px;display:grid;place-items:center;font-weight:800;color:#fff;background:linear-gradient(145deg,var(--gold),#a7833f);box-shadow:0 10px 16px -8px rgba(138,106,44,.8)}
.outcome h4{font-size:15px;margin-bottom:2px}
.outcome p{font-size:13.5px;color:var(--ink-2)}
.stack{margin-top:26px;display:flex;flex-wrap:wrap;gap:8px}
.stack span{font-size:12px;font-weight:700;padding:8px 12px;border-radius:10px;background:#fff;box-shadow:0 1px 0 #fff inset, 0 6px 14px -8px rgba(15,34,25,.35);color:var(--green-700)}
.stack span.hl{background:var(--green-800);color:#fff}

/* ---------- Footer credits ---------- */
.credits{background:var(--green-900);color:#cfdcd3;padding:44px 0 calc(34px + env(safe-area-inset-bottom));position:relative;overflow:hidden}
.credits .ring{width:140px;height:140px;right:-40px;top:-40px;opacity:.5;background:linear-gradient(var(--green-900),var(--green-900)) padding-box, linear-gradient(145deg,var(--gold-2),var(--gold) 50%,#8a6a2c) border-box}
.dev{display:grid;gap:18px;position:relative}
.dev-id{display:flex;gap:14px;align-items:center}
.avatar{width:58px;height:58px;border-radius:18px;display:grid;place-items:center;font-family:var(--font-d);font-size:22px;color:var(--green-900);background:linear-gradient(145deg,var(--gold-2),var(--gold));box-shadow:0 14px 24px -12px rgba(0,0,0,.6), inset 0 1px 0 rgba(255,255,255,.6)}
.dev-id h3{color:#fff;font-size:22px}
.dev-id p{font-size:13px;color:#9fb4a6}
.socials{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.socials a{display:flex;align-items:center;gap:8px;padding:11px 12px;border-radius:12px;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.08);text-decoration:none;font-size:12.5px;font-weight:600;color:#e5eee8;transition:background .2s,transform .2s;min-width:0}
.socials a:hover{background:rgba(255,255,255,.1);transform:translateY(-2px)}
.socials a span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.socials svg{flex:0 0 16px;width:16px;height:16px;fill:var(--gold-2)}
.copy{margin-top:26px;padding-top:18px;border-top:1px solid rgba(255,255,255,.08);font-size:12px;color:#8aa093;display:flex;flex-wrap:wrap;gap:6px 14px;justify-content:space-between}

/* reveal */
.rv{opacity:0;transform:translateY(24px);transition:opacity .8s ease, transform .8s cubic-bezier(.2,.7,.2,1)}
.rv.in{opacity:1;transform:none}

/* =================== BREAKPOINTS (mobile-first) =================== */
@media (max-width:419.98px){
  .meta dd{font-size:12.5px}
  .chip{font-size:11px;padding:7px 10px}
  .chip b{font-size:16px}
  .chip-2{display:none}
  .stage{height:360px}
  .phone{width:128px}
  .reel{width:128px}
  .stat b{font-size:32px}
}
@media (min-width:420px){
  :root{--pad:22px}
  .stage{height:450px}
  .phone{width:165px}
  .socials a{font-size:13px}
}
@media (min-width:580px){
  :root{--pad:28px}
  body{font-size:16px}
  .brand small{display:inline}
  .meta{grid-template-columns:repeat(4,1fr)}
  .stage{height:520px}
  .phone{width:190px;right:4%}
  .problems{grid-template-columns:1fr 1fr}
  .features{grid-template-columns:1fr 1fr}
  .impact{grid-template-columns:repeat(4,1fr)}
  .reel{width:170px}
  .reel-stage{height:380px}
  .socials{grid-template-columns:repeat(3,1fr)}
  .reqs{padding:28px}
}
@media (min-width:768px){
  :root{--pad:36px}
  section.block{padding:84px 0}
  .hero{padding:56px 0 70px}
  .stage{height:560px}
  .phone{width:210px}
  .sec-head{grid-template-columns:auto 1fr;align-items:end;gap:10px 28px}
  .sec-head .sec-num{grid-row:span 2;font-size:110px}
  .hero-feature{padding:34px}
  .gallery{grid-template-columns:1fr 1fr}
  .gallery .shot:first-child{grid-column:1/-1}
  .gallery .shot:first-child img{aspect-ratio:16/7}
  .outcomes{grid-template-columns:repeat(3,1fr)}
  .outcome{flex-direction:column}
  .dev{grid-template-columns:1fr 1.4fr;align-items:center}
}
@media (min-width:990px){
  .hero-grid{grid-template-columns:1fr 1.1fr;align-items:center;gap:30px}
  .hero h1{font-size:clamp(60px,6.4vw,92px)}
  .stage{height:560px}
  .laptop{width:96%;left:-4%;top:40px}
  .phone{width:190px;right:-1%;bottom:10px}
  .problems{grid-template-columns:repeat(4,1fr)}
  .hero-feature{grid-template-columns:1.05fr 1fr;align-items:center;padding:48px;gap:40px}
  .reel-stage{height:440px}
  .reel{width:190px}
  .features{grid-template-columns:repeat(3,1fr)}
  .gallery:hover .shot{transform:rotateY(-6deg) rotateX(3deg)}
  .gallery .shot:hover{transform:translateZ(40px) rotateY(0) !important}
}
@media (min-width:1280px){
  :root{--pad:24px}
  .phone{width:220px}
}
@media (hover:none){ .gallery:hover .shot{transform:none} }
@media (prefers-reduced-motion:reduce){
  *,*::before,*::after{animation:none!important;transition:none!important}
  .rv{opacity:1;transform:none}
}
</style>
</head>
<body>

<header class="topbar">
  <div class="wrap">
    <a class="brand" href="https://sazzad.wedevspro.com" target="_blank" rel="noopener">
      <span class="brand-mark">SH</span>
