    <!-- Impact -->
    <div class="impact">
      <div class="stat rv"><b data-count="158">158</b><span>Products online</span></div>
      <div class="stat rv"><b data-count="16">16</b><span>Organised categories</span></div>
      <div class="stat rv"><b>1-tap</b><span>WhatsApp / call from any page</span></div>
      <div class="stat rv"><b>24/7</b><span>Self-serve ordering</span></div>
    </div>
    <div class="outcomes">
      <div class="outcome rv"><span class="n">1</span><div><h4>From DMs to checkout</h4><p>Customers can browse, pick a size and pay on their own. Chat is now for support, not for taking orders.</p></div></div>
      <div class="outcome rv"><span class="n">2</span><div><h4>Video traffic converts</h4><p>Reel viewers land on a reel that is linked to the product, so they're one tap from the cart.</p></div></div>
      <div class="outcome rv"><span class="n">3</span><div><h4>Owner in control</h4><p>New products, sale tags and homepage banners are managed in WordPress, with no developer needed.</p></div></div>
    </div>

    <div class="stack rv" aria-label="Tech stack">
      <span class="hl">WordPress</span><span class="hl">WooCommerce</span><span>Woodmart + Child Theme</span><span>Elementor / Pro Elements</span><span>Slider Revolution</span><span>PayPal Payments</span><span>Chaty (WhatsApp)</span><span>Product Size Chart</span><span>Contact Form 7</span><span class="hl">Custom Plugin · PHP + JS</span>
    </div>
  </div>
</section>
</main>

