<script>
(function(){
  // Reveal on scroll
  var els=document.querySelectorAll('.rv');
  if('IntersectionObserver' in window){
    var io=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target);}})},{threshold:.12,rootMargin:'0px 0px -40px 0px'});
    els.forEach(function(el){io.observe(el)});
  } else els.forEach(function(el){el.classList.add('in')});

  var fine=window.matchMedia('(hover:hover) and (pointer:fine)').matches;
  var reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if(!fine||reduce) return;

  // Hero 3D parallax
  var stage=document.getElementById('stage'), inner=document.getElementById('stageInner');
  stage.addEventListener('mousemove',function(e){
    var r=stage.getBoundingClientRect(), x=(e.clientX-r.left)/r.width-.5, y=(e.clientY-r.top)/r.height-.5;
    inner.style.transform='rotateY('+(x*10)+'deg) rotateX('+(-y*8)+'deg)';
  });
  stage.addEventListener('mouseleave',function(){inner.style.transform='';});

  // Card tilt
  document.querySelectorAll('.tilt').forEach(function(c){
    c.addEventListener('mousemove',function(e){
      var r=c.getBoundingClientRect(), x=(e.clientX-r.left)/r.width-.5, y=(e.clientY-r.top)/r.height-.5;
      c.style.transform='perspective(800px) rotateY('+(x*10)+'deg) rotateX('+(-y*10)+'deg) translateY(-4px)';
    });
    c.addEventListener('mouseleave',function(){c.style.transform='';});
  });
})();
</script>
